var e={kind:`array`,render:`cells`,caption:`intervals = [[2,6], [15,18], [1,3], [9,12], [8,10], [4,5], [6,7]]`,cells:[`[1,3]`,`[2,6]`,`[4,5]`,`[6,7]`,`[8,10]`,`[9,12]`,`[15,18]`],frames:[{step:0,note:`原始输入是乱序的：[2,6] 排在 [1,3] 前面，谁和谁可能重叠根本看不出来。`,marks:{},state:{},band:null,bands:[],aux:{title:`res（结果列表）`,rows:[],empty:`还是空的`},over:null,cells:[`[2,6]`,`[15,18]`,`[1,3]`,`[9,12]`,`[8,10]`,`[4,5]`,`[6,7]`],rows:[],out:null},{step:0,note:`按左端点从小到大排完：[1,3] [2,6] [4,5] [6,7] [8,10] [9,12] [15,18]。排序买到的是一条保证 —— 能重叠的区间一定彼此相邻，于是只需拿当前区间和 res 的最后一段比，不必两两都比。`,marks:{},state:{},band:null,bands:[],aux:{title:`res（结果列表）`,rows:[],empty:`还是空的`},over:null,cells:[`[1,3]`,`[2,6]`,`[4,5]`,`[6,7]`,`[8,10]`,`[9,12]`,`[15,18]`],rows:[],out:null},{step:1,note:`res 先是空的。往后每一步都只看 res 的最后一段：它是唯一还可能被后面区间碰到的。`,marks:{},state:{},band:null,bands:[],aux:{title:`res（结果列表）`,rows:[],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`第一个区间 it = [1,3]，res 还是空的，没有"上一段"可比。`,marks:{it:0},state:{0:`active`},band:null,bands:[],aux:{title:`res（结果列表）`,rows:[],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:3,note:`直接放进 res 当第一段。放的是拷贝 it[:] —— 后面要就地改它的右端点，拷一份才不会连原始数组一起改掉。（"段首"标的是：被压进 res 末项的那一段从哪个格子开始，高亮区间就是这一段，它会随着合并往右变长。）`,marks:{it:0,段首:0},state:{0:`done`},band:{from:0,to:0},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,3]`,!0]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`轮到 it = [2,6]。只要比一件事：它的左端点 2，和 res 末项 [1,3] 的右端点 3，谁大。`,marks:{it:1,段首:0},state:{0:`done`,1:`active`},band:{from:0,to:0},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,3]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:2,note:`2 ≤ 3，两段搭上了。不是往 res 里新增一段，而是把末项的右端点从 3 就地拉长到 6：[1,3] → [1,6]。`,marks:{it:1,段首:0},state:{0:`done`,1:`hit`},band:{from:0,to:1},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,3] → [1,6]`,!0]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`轮到 it = [4,5]。只要比一件事：它的左端点 4，和 res 末项 [1,6] 的右端点 6，谁大。`,marks:{it:2,段首:0},state:{0:`done`,1:`done`,2:`active`},band:{from:0,to:1},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,6]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:2,note:`4 ≤ 6，重叠。但 5 比 6 还小，[4,5] 整个被 [1,6] 包住了，取 max 之后右端点仍是 6 —— 这正是必须写 max、不能直接赋 it[1] 的原因，否则末项会被错误地缩短成 [1,5]。`,marks:{it:2,段首:0},state:{0:`done`,1:`done`,2:`dim`},band:{from:0,to:2},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,6]（取 max 后原样不动）`,!0]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`轮到 it = [6,7]。只要比一件事：它的左端点 6，和 res 末项 [1,6] 的右端点 6，谁大。`,marks:{it:3,段首:0},state:{0:`done`,1:`done`,2:`dim`,3:`active`},band:{from:0,to:2},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,6]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:2,note:`左端点 6 正好等于末项右端点 6：端点相接也算重叠（判断写的是 ≤ 而不是 <），把右端点从 6 就地拉长到 7。`,marks:{it:3,段首:0},state:{0:`done`,1:`done`,2:`dim`,3:`hit`},band:{from:0,to:3},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,6] → [1,7]`,!0]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`轮到 it = [8,10]。只要比一件事：它的左端点 8，和 res 末项 [1,7] 的右端点 7，谁大。`,marks:{it:4,段首:0},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`active`},band:{from:0,to:3},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:3,note:`8 > 7，中间断开了，[8,10] 和前面粘不上。既然已排序，后面的左端点只会更大，末项 [1,7] 从此定型，把 it 拷一份作为新的一段加进 res。`,marks:{it:4,段首:0},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`active`},band:{from:0,to:3},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:3,note:`res 现在有 2 段，新的末项是 [8,10]，接下来都跟它比。`,marks:{it:4,段首:4},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`done`},band:{from:4,to:4},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1],[`res[1]`,`[8,10]`,!0]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`轮到 it = [9,12]。只要比一件事：它的左端点 9，和 res 末项 [8,10] 的右端点 10，谁大。`,marks:{it:5,段首:4},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`done`,5:`active`},band:{from:4,to:4},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1],[`res[1]`,`[8,10]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:2,note:`9 ≤ 10，两段搭上了。不是往 res 里新增一段，而是把末项的右端点从 10 就地拉长到 12：[8,10] → [8,12]。`,marks:{it:5,段首:4},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`done`,5:`hit`},band:{from:4,to:5},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1],[`res[1]`,`[8,10] → [8,12]`,!0]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`轮到 it = [15,18]。只要比一件事：它的左端点 15，和 res 末项 [8,12] 的右端点 12，谁大。`,marks:{it:6,段首:4},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`done`,5:`done`,6:`active`},band:{from:4,to:5},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1],[`res[1]`,`[8,12]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:3,note:`15 > 12，中间断开了，[15,18] 和前面粘不上。既然已排序，后面的左端点只会更大，末项 [8,12] 从此定型，把 it 拷一份作为新的一段加进 res。`,marks:{it:6,段首:4},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`done`,5:`done`,6:`active`},band:{from:4,to:5},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1],[`res[1]`,`[8,12]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:3,note:`res 现在有 3 段，新的末项是 [15,18]，接下来都跟它比。`,marks:{it:6,段首:6},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`done`,5:`done`,6:`done`},band:{from:6,to:6},bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1],[`res[1]`,`[8,12]`,!1],[`res[2]`,`[15,18]`,!0]],empty:`还是空的`},over:null,cells:null,rows:[],out:null},{step:1,note:`全部扫完，res 里这 3 段两两不重叠。整趟只扫了一遍，真正的开销在开头那次排序（O(n log n)）。`,marks:{},state:{0:`done`,1:`done`,2:`dim`,3:`done`,4:`done`,5:`done`,6:`done`},band:null,bands:[],aux:{title:`res（结果列表）`,rows:[[`res[0]`,`[1,7]`,!1],[`res[1]`,`[8,12]`,!1],[`res[2]`,`[15,18]`,!1]],empty:`还是空的`},over:null,cells:null,rows:[],out:`[[1,7], [8,12], [15,18]]`}]};export{e as default};